 rows.sort(reverse=True)
 top=rows[:topn]
 expmap={c['exp']:c for c in cands_all}
 subset=[expmap[e] for _,e in top]
 outfile=f'stage2_top{topn}.jsonl'
 t=time.time(); done=0
 with open(outfile,'w') as out, concurrent.futures.ProcessPoolExecutor(max_workers=workers) as ex:
  futs=[ex.submit(work,c) for c in subset]
  for fut in concurrent.futures.as_completed(futs):
   r=fut.result(); done+=1
   out.write(json.dumps(r)+'\\n'); out.flush()
   if done%10==0: print(done,'/',len(subset),'elapsed',time.time()-t,'last',r.get('exp'),r.get('corr'),r.get('spear'), flush=True)
 print('done',outfile,'elapsed',time.time()-t)
